document.addEventListener("DOMContentLoaded",function(){function n(n){return Math.round(n).toLocaleString("en-US",{style:"currency",currency:"USD",minimumFractionDigits:2,maximumFractionDigits:2})}function t(n){return Math.round(100*n)/100}const e=document.getElementById("markup-margin-form"),i=document.getElementById("markup-margin-result");e&&e.addEventListener("submit",function(e){e.preventDefault();let r=parseFloat(document.getElementById("cost").value),l=parseFloat(document.getElementById("price").value),s=parseFloat(document.getElementById("margin").value),o=parseFloat(document.getElementById("markup").value),a={cost:!isNaN(r),price:!isNaN(l),margin:!isNaN(s),markup:!isNaN(o)};if(Object.values(a).filter(Boolean).length<2)return i.innerHTML='<span style="color:red">Please enter at least two parameters for calculation.</span>',void 0;if(a.cost&&a.price){const e=l-r,s=e/l*100,o=e/r*100;i.innerHTML=`\n          <h3>Calculation Results:</h3>\n          <div style="background: #f8f9fa; padding: 1rem; border-radius: 5px;">\n            <ul style="list-style: none; padding: 0; margin: 0;">\n              <li><strong>Margin:</strong> ${t(s)}%</li>\n              <li><strong>Markup:</strong> ${t(o)}%</li>\n              <li><strong>Profit:</strong> ${n(e)}</li>\n            </ul>\n          </div>\n        `}else if(a.cost&&a.markup){const e=r*o/100,l=r+e,s=e/l*100;i.innerHTML=`\n          <h3>Calculation Results:</h3>\n          <div style="background: #f8f9fa; padding: 1rem; border-radius: 5px;">\n            <ul style="list-style: none; padding: 0; margin: 0;">\n              <li><strong>Selling Price:</strong> ${n(l)}</li>\n              <li><strong>Margin:</strong> ${t(s)}%</li>\n              <li><strong>Profit:</strong> ${n(e)}</li>\n            </ul>\n          </div>\n        `}else if(a.cost&&a.margin){const e=r/(1-s/100),l=e-r,o=l/r*100;i.innerHTML=`\n          <h3>Calculation Results:</h3>\n          <div style="background: #f8f9fa; padding: 1rem; border-radius: 5px;">\n            <ul style="list-style: none; padding: 0; margin: 0;">\n              <li><strong>Selling Price:</strong> ${n(e)}</li>\n              <li><strong>Markup:</strong> ${t(o)}%</li>\n              <li><strong>Profit:</strong> ${n(l)}</li>\n            </ul>\n          </div>\n        `}else if(a.price&&a.margin){const e=l*s/100,r=l-e,o=e/r*100;i.innerHTML=`\n          <h3>Calculation Results:</h3>\n          <div style="background: #f8f9fa; padding: 1rem; border-radius: 5px;">\n            <ul style="list-style: none; padding: 0; margin: 0;">\n              <li><strong>Cost Price:</strong> ${n(r)}</li>\n              <li><strong>Markup:</strong> ${t(o)}%</li>\n              <li><strong>Profit:</strong> ${n(e)}</li>\n            </ul>\n          </div>\n        `}else if(a.price&&a.markup){const e=l/(1+o/100),r=l-e,s=r/l*100;i.innerHTML=`\n          <h3>Calculation Results:</h3>\n          <div style="background: #f8f9fa; padding: 1rem; border-radius: 5px;">\n            <ul style="list-style: none; padding: 0; margin: 0;">\n              <li><strong>Cost Price:</strong> ${n(e)}</li>\n              <li><strong>Margin:</strong> ${t(s)}%</li>\n              <li><strong>Profit:</strong> ${n(r)}</li>\n            </ul>\n          </div>\n        `}else i.innerHTML='<span style="color:red">Please enter a valid combination of two parameters for calculation.</span>'})});